## MSTest Comparison Assertions for Boundary Checking

MSTest 3.x+ provides these comparison assertions (from `Assert`):

```csharp
Assert.IsGreaterThan(lowerBound, actual);   // actual > lowerBound
Assert.IsLessThan(upperBound, actual);      // actual < upperBound
Assert.IsInRange(actual, low, high);        // low <= actual <= high
```

### Example tests for your `ScoreCalculator`

```csharp
[TestClass]
public sealed class ScoreCalculatorTests
{
    private readonly ScoreCalculator _calc = new();

    [TestMethod]
    public void CalculatePercentage_PartialScore_ReturnsValueInRange()
    {
        var result = _calc.CalculatePercentage(7, 10);

        Assert.AreEqual(70.0, result);
    }

    [TestMethod]
    [DataRow(9, 10, 90.0)]
    [DataRow(8, 10, 80.0)]
    [DataRow(7, 10, 70.0)]
    [DataRow(6, 10, 60.0)]
    [DataRow(5, 10, 50.0)]
    public void CalculatePercentage_BoundaryValues_ReturnsExpected(
        int correct, int total, double expected)
    {
        Assert.AreEqual(expected, _calc.CalculatePercentage(correct, total));
    }

    [TestMethod]
    public void NormalizeScore_BelowMax_ReturnsValueInRange()
    {
        var result = _calc.NormalizeScore(75, 150);

        Assert.IsInRange(result, 0.0, 100.0);  // always within [0, 100]
        Assert.AreEqual(50.0, result);
    }

    [TestMethod]
    public void NormalizeScore_ExceedsMax_CapsAt100()
    {
        var result = _calc.NormalizeScore(200, 100);

        Assert.AreEqual(100.0, result);         // capped
        Assert.IsInRange(result, 0.0, 100.0);   // invariant holds
    }

    [TestMethod]
    public void NormalizeScore_PartialCredit_IsGreaterThanZero()
    {
        var result = _calc.NormalizeScore(1, 100);

        Assert.IsGreaterThan(0.0, result);      // result > 0
        Assert.IsLessThan(100.0, result);       // result < 100
    }

    [TestMethod]
    [DataRow(90.0, "A")]
    [DataRow(89.99, "B")]
    [DataRow(80.0, "B")]
    [DataRow(79.99, "C")]
    [DataRow(70.0, "C")]
    [DataRow(60.0, "D")]
    [DataRow(59.99, "F")]
    public void GetGrade_BoundaryPercentages_ReturnsCorrectGrade(
        double percentage, string expected)
    {
        Assert.AreEqual(expected, _calc.GetGrade(percentage));
    }

    [TestMethod]
    public void CalculatePercentage_NegativeCorrect_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calc.CalculatePercentage(-1, 10));
    }

    [TestMethod]
    public void CalculatePercentage_CorrectExceedsTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calc.CalculatePercentage(11, 10));
    }
}
```

### Key takeaways

| Assertion | Meaning |
|-----------|---------|
| `Assert.IsGreaterThan(0.0, result)` | result > 0 |
| `Assert.IsLessThan(100.0, result)` | result < 100 |
| `Assert.IsInRange(result, 0.0, 100.0)` | 0 ≤ result ≤ 100 |

These give much better failure messages than `Assert.IsTrue(result > 0)` — on failure they report the actual value and the bound that was violated.
